import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sigmoid_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor sigmoid_forward(torch::Tensor x);
"""

sigmoid_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cstdint>
#include <cute/tensor.hpp>

using namespace cute;

template <int Threads, int ItemsPerThread, bool UseVec>
__global__ void sigmoid_cute_kernel(const float* __restrict__ X,
                                    float* __restrict__ Y,
                                    int64_t N)
{
  // Flat CUTE views over global memory.
  Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(N));
  Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(N));
  constexpr int Vec = 4;
  if constexpr (UseVec) {
    // Vectorized path: process the bulk of the tensor in float4 chunks.
    const int64_t Nvec = N / Vec;
    Tensor vX = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(X)), make_shape(Nvec));
    Tensor vY = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(Y)), make_shape(Nvec));
    constexpr int VecsPerThread = ItemsPerThread / Vec;
    constexpr int Tile = Threads * VecsPerThread;  // float4 chunks per CTA per iteration
    const int64_t tile_base = (int64_t)blockIdx.x * Tile;
    const int64_t stride    = (int64_t)gridDim.x * Tile;
    for (int64_t base = tile_base; base < Nvec; base += stride) {
      #pragma unroll
      for (int i = 0; i < VecsPerThread; ++i) {
        const int64_t idx = base + (int64_t)threadIdx.x + (int64_t)i * Threads;
        if (idx < Nvec) {
          float4 v = vX(idx);
          float4 o;
          o.x = 1.0f / (1.0f + expf(-v.x));
          o.y = 1.0f / (1.0f + expf(-v.y));
          o.z = 1.0f / (1.0f + expf(-v.z));
          o.w = 1.0f / (1.0f + expf(-v.w));
          vY(idx) = o;
        }
      }
    }
    // Scalar tail for the remaining N % 4 elements.
    const int64_t tail_begin = Nvec * Vec;
    const int64_t gtid    = (int64_t)blockIdx.x * Threads + threadIdx.x;
    const int64_t gstride = (int64_t)gridDim.x * Threads;
    for (int64_t idx = tail_begin + gtid; idx < N; idx += gstride) {
      float v = mX(idx);
      mY(idx) = 1.0f / (1.0f + expf(-v));
    }
  } else {
    // Scalar fallback path (used only if pointers are not 16-byte aligned).
    constexpr int Tile = Threads * ItemsPerThread;
    const int64_t tile_base = (int64_t)blockIdx.x * Tile;
    const int64_t stride    = (int64_t)gridDim.x * Tile;
    for (int64_t base = tile_base; base < N; base += stride) {
      #pragma unroll
      for (int i = 0; i < ItemsPerThread; ++i) {
        const int64_t idx = base + (int64_t)threadIdx.x + (int64_t)i * Threads;
        if (idx < N) {
          float v = mX(idx);
          mY(idx) = 1.0f / (1.0f + expf(-v));
        }
      }
    }
  }
}

torch::Tensor sigmoid_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  const int64_t N = x_c.numel();
  if (N == 0) {
    return y;
  }

  constexpr int Threads = 256;
  constexpr int ItemsPerThread = 8;
  constexpr int Tile = Threads * ItemsPerThread;

  int64_t grid64 = (N + Tile - 1) / Tile;
  if (grid64 > 2147483647LL) {
    grid64 = 2147483647LL;
  }

  dim3 block(Threads);
  dim3 grid((unsigned)grid64);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  const bool aligned =
      (reinterpret_cast<uintptr_t>(x_c.data_ptr<float>()) % 16 == 0) &&
      (reinterpret_cast<uintptr_t>(y.data_ptr<float>()) % 16 == 0);
  if (aligned) {
    sigmoid_cute_kernel<Threads, ItemsPerThread, true><<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        N
    );
  } else {
    sigmoid_cute_kernel<Threads, ItemsPerThread, false><<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        N
    );
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "sigmoid_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

sigmoid_ext = load_inline(
    name="cute_sigmoid_ext",
    cpp_sources=sigmoid_cpp_decl,
    cuda_sources=sigmoid_cuda_src,
    functions=["sigmoid_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Sigmoid activation implemented with a single custom CUTE/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = sigmoid_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.sigmoid_forward(x)

